import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'app-button',
  template: `
    <button
      class="mt-4 border-2 rounded-2"
      style="padding: 2px 10px; background-color: transparent"
      (click)="onEmitClickBtn.emit()"
    >
      <ng-container *ngIf="isEditMode; else createMode">
        <i class="bi bi-pencil small"></i> {{ buttonType }}
      </ng-container>

      <ng-template #createMode> + Add {{ buttonType }} </ng-template>

      <!-- <ng-content select="[selector]">
        <ng-container *ngIf=""></ng-container>
      </ng-content> -->
    </button>
  `,
  styles: [],
})
export class ButtonComponent {
  @Input() buttonType!: string;
  @Input() isEditMode!: boolean;
  @Output() onEmitClickBtn: EventEmitter<void> = new EventEmitter();
}
